def solve(inputs: dict) -> float:
    # Matrix exponentiation with modular reduction
    M = inputs['matrix']
    power = inputs['power']
    mod = inputs['modulus']

    def matrix_mult(A, B, m):
        """Multiply two 2x2 matrices modulo m"""
        n = len(A)
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % m
        return result

    def matrix_pow(M, exp, m):
        """Compute M^exp mod m using binary exponentiation"""
        n = len(M)
        # Identity matrix
        result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
        base = [row[:] for row in M]

        while exp > 0:
            if exp % 2 == 1:
                result = matrix_mult(result, base, m)
            base = matrix_mult(base, base, m)
            exp //= 2

        return result

    result_matrix = matrix_pow(M, power, mod)

    # Sum all entries
    total = sum(sum(row) for row in result_matrix)
    return float(total % mod)

